module traffic_light_mealy (
    input logic clk,
    input logic rst_n,
    input logic pedestrian_req,
    output logic [1:0] lights,  // 00: Green, 01: Yellow, 10: Red
    output logic walk_signal
);

typedef enum logic [1:0] {GREEN, YELLOW, RED} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= GREEN;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    lights = {2{1'b0}};
    walk_signal = 1'b0;

    case (state)
        GREEN: begin
            lights = 2'b00;  // Green
            if (pedestrian_req) begin
                next_state = YELLOW;
                walk_signal = 1'b1;  // Walk signal triggered immediately
            end
        end

        YELLOW: begin
            lights = 2'b01;  // Yellow
            // Count 3 cycles then change to red
            // (simplified - normally would have counter)
            next_state = RED;
        end

        RED: begin
            lights = 2'b10;  // Red
            // After pedestrian crossing time
            next_state = GREEN;
        end
    endcase
end

endmodule

module serial_adder_mealy (
    input logic clk,
    input logic rst_n,
    input logic a_bit,
    input logic b_bit,
    input logic valid,
    output logic sum_bit,
    output logic carry_out
);

typedef enum logic {C0, C1} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    sum_bit = 1'b0;
    carry_out = 1'b0;

    if (valid) begin
        case (state)
            C0: begin  // Carry = 0
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b0;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b11: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                endcase
            end

            C1: begin  // Carry = 1
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                    2'b11: begin
                        sum_bit = 1'b1;
                        next_state = C1;
                    end
                endcase
            end
        endcase

        // Final carry out
        if (state == C1 && {a_bit, b_bit} != 2'b00)
            carry_out = 1'b1;
    end
end

endmodule

module arbiter_mealy (
    input logic clk,
    input logic rst_n,
    input logic req1,
    input logic req2,
    output logic grant1,
    output logic grant2
);

typedef enum logic {IDLE, GRANT1, GRANT2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    grant1 = 1'b0;
    grant2 = 1'b0;

    case (state)
        IDLE: begin
            if (req1) begin
                next_state = GRANT1;
                grant1 = 1'b1;  // Grant immediately
            end
            else if (req2) begin
                next_state = GRANT2;
                grant2 = 1'b1;  // Grant immediately
            end
        end

        GRANT1: begin
            if (!req1) begin
                next_state = IDLE;
            end
            else if (req2) begin
                grant1 = 1'b1;  // Keep grant while req1 still high
            end
        end

        GRANT2: begin
            if (!req2) begin
                next_state = IDLE;
            end
            else if (req1) begin
                grant2 = 1'b1;  // Keep grant while req2 still high
            end
        end
    endcase
end

endmodule

module adaptive_fir_filter (
    input logic clk,
    input logic rst_n,
    input logic signed [15:0] sample_in,
    input logic signed [15:0] desired_out,
    input logic [1:0] mode,  // 00: BYPASS, 01: LOWPASS, 10: HIGHPASS, 11: ADAPTIVE
    input logic update_coeffs,
    output logic signed [31:0] filtered_out,
    output logic signed [15:0] coeffs [0:7],
    output logic [2:0] tap_count
);

typedef enum logic [2:0] {
    IDLE,
    LOAD_COEFFS,
    PROCESS_TAP0,
    PROCESS_TAP1,
    PROCESS_TAP2,
    PROCESS_TAP3,
    PROCESS_TAP4,
    PROCESS_TAP5,
    ACCUMULATE,
    ADAPT
} state_t;

state_t state, next_state;
logic signed [15:0] coeff_ram [0:7];
logic signed [15:0] data_shift_reg [0:7];
logic signed [31:0] accumulator;
logic [2:0] tap_index;
logic signed [31:0] error_signal;
logic [15:0] step_size;

// LMS adaptation parameters
parameter STEP_SIZE_INIT = 16'h0100;
parameter STEP_SIZE_MAX = 16'h1000;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        tap_index <= 3'b0;
        accumulator <= 32'b0;
        step_size <= STEP_SIZE_INIT;

        for (int i = 0; i < 8; i++) begin
            coeff_ram[i] <= 16'b0;
            data_shift_reg[i] <= 16'b0;
        end
    end else begin
        state <= next_state;

        // Data path operations
        unique case (state)
            IDLE: begin
                // Shift in new sample
                data_shift_reg[0] <= sample_in;
                for (int i = 1; i < 8; i++)
                    data_shift_reg[i] <= data_shift_reg[i-1];
            end

            PROCESS_TAP0, PROCESS_TAP1, PROCESS_TAP2,
            PROCESS_TAP3, PROCESS_TAP4, PROCESS_TAP5: begin
                tap_index <= tap_index + 1;
            end

            ACCUMULATE: begin
                accumulator <= accumulator +
                               (coeff_ram[tap_index] * data_shift_reg[tap_index]);
            end

            ADAPT: begin
                // LMS adaptation algorithm
                error_signal <= desired_out - accumulator[31:16];

                // Update coefficients based on error
                for (int i = 0; i < 8; i++) begin
                    if (mode == 2'b11) begin  // Adaptive mode
                        coeff_ram[i] <= coeff_ram[i] +
                                       (error_signal[23:8] * data_shift_reg[i] * step_size) >> 16;
                    end
                end

                // Adjust step size based on convergence
                if (error_signal < 32'h1000)
                    step_size <= step_size + 1;
                else if (error_signal > 32'h10000)
                    step_size <= step_size >> 1;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    filtered_out = accumulator;
    coeffs = coeff_ram;
    tap_count = tap_index;

    // Coefficient selection based on mode
    logic signed [15:0] lowpass_coeffs [0:7];
    logic signed [15:0] highpass_coeffs [0:7];

    // Predefined coefficient sets
    lowpass_coeffs = '{16'h1000, 16'h2000, 16'h3000, 16'h4000,
                       16'h3000, 16'h2000, 16'h1000, 16'h0800};
    highpass_coeffs = '{16'h1000, -16'h2000, 16'h3000, -16'h4000,
                        16'h3000, -16'h2000, 16'h1000, -16'h0800};

    case (state)
        IDLE: begin
            accumulator = 32'b0;
            tap_index = 3'b0;

            unique case (mode)
                2'b00: begin  // BYPASS
                    filtered_out = sample_in * 16;
                    next_state = IDLE;
                end

                2'b01: begin  // LOWPASS
                    for (int i = 0; i < 8; i++)
                        coeff_ram[i] = lowpass_coeffs[i];
                    next_state = PROCESS_TAP0;
                end

                2'b10: begin  // HIGHPASS
                    for (int i = 0; i < 8; i++)
                        coeff_ram[i] = highpass_coeffs[i];
                    next_state = PROCESS_TAP0;
                end

                2'b11: begin  // ADAPTIVE
                    if (update_coeffs)
                        next_state = ADAPT;
                    else
                        next_state = PROCESS_TAP0;
                end
            endcase
        end

        PROCESS_TAP0: begin
            accumulator = coeff_ram[0] * data_shift_reg[0];
            next_state = PROCESS_TAP1;
        end

        PROCESS_TAP1: begin
            accumulator = accumulator + coeff_ram[1] * data_shift_reg[1];
            next_state = PROCESS_TAP2;
        end

        PROCESS_TAP2: begin
            accumulator = accumulator + coeff_ram[2] * data_shift_reg[2];
            next_state = PROCESS_TAP3;
        end

        PROCESS_TAP3: begin
            accumulator = accumulator + coeff_ram[3] * data_shift_reg[3];
            next_state = PROCESS_TAP4;
        end

        PROCESS_TAP4: begin
            accumulator = accumulator + coeff_ram[4] * data_shift_reg[4];
            next_state = PROCESS_TAP5;
        end

        PROCESS_TAP5: begin
            accumulator = accumulator + coeff_ram[5] * data_shift_reg[5];
            next_state = ACCUMULATE;
        end

        ACCUMULATE: begin
            accumulator = accumulator + coeff_ram[6] * data_shift_reg[6] +
                         coeff_ram[7] * data_shift_reg[7];

            // Output scaling
            filtered_out = accumulator >>> 4;

            if (mode == 2'b11 && update_coeffs)
                next_state = ADAPT;
            else
                next_state = IDLE;
        end

        ADAPT: begin
            filtered_out = accumulator >>> 4;
            next_state = IDLE;
        end
    endcase
end

endmodule

module counter_2bit_mealy (
    input logic clk,
    input logic rst_n,
    input logic enable,
    output logic [1:0] count,
    output logic overflow
);

typedef enum logic [1:0] {C0, C1, C2, C3} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Output logic for current count
assign count = state;

// Next state and overflow detection
always_comb begin
    next_state = state;
    overflow = 1'b0;

    if (enable) begin
        case (state)
            C0: next_state = C1;
            C1: next_state = C2;
            C2: next_state = C3;
            C3: begin
                next_state = C0;
                overflow = 1'b1;  // Overflow on transition
            end
        endcase
    end
end

endmodule

module parity_checker_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    input logic valid,
    output logic error
);

typedef enum logic {EVEN, ODD} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= EVEN;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    error = 1'b0;

    if (valid) begin
        case (state)
            EVEN: begin
                if (din) begin
                    next_state = ODD;
                end
                // Error detection on final valid
                error = 1'b0;  // Even parity with even bits is OK
            end

            ODD: begin
                if (!din) begin
                    next_state = EVEN;
                end
                // Error detection on final valid
                error = 1'b1;  // Odd parity with odd bits is error
            end
        endcase
    end
end

endmodule

module binary_to_bcd_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] binary_in,
    input logic convert,
    output logic [3:0] bcd_out,
    output logic bcd_valid
);

typedef enum logic [2:0] {IDLE, SHIFT, ADD3, DONE} state_t;
state_t state, next_state;
logic [7:0] binary_reg;
logic [11:0] bcd_reg;
logic [2:0] bit_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        binary_reg <= 8'b0;
        bcd_reg <= 12'b0;
        bit_count <= 3'b0;
    end else begin
        state <= next_state;
        if (state == SHIFT) begin
            binary_reg <= {binary_reg[6:0], 1'b0};
            bcd_reg <= {bcd_reg[10:0], binary_reg[7]};
            bit_count <= bit_count + 1;
        end
        if (state == ADD3)
            // Add 3 to each BCD digit > 4
            bcd_reg <= bcd_reg;
    end
end

always_comb begin
    next_state = state;
    bcd_out = 4'b0;
    bcd_valid = 1'b0;

    case (state)
        IDLE: begin
            if (convert) begin
                next_state = SHIFT;
                binary_reg = binary_in;
                bcd_reg = 12'b0;
                bit_count = 3'b0;
            end
        end

        SHIFT: begin
            if (bit_count == 3'b111) begin
                next_state = DONE;
                // Output on last shift
                bcd_out = bcd_reg[11:8];  // MSB digit
                bcd_valid = 1'b1;
            end else begin
                // Check if any BCD digit > 4
                if (bcd_reg[11:8] > 4 || bcd_reg[7:4] > 4 || bcd_reg[3:0] > 4)
                    next_state = ADD3;
            end
        end

        ADD3: begin
            // Immediate addition of 3 to digits > 4
            next_state = SHIFT;
        end

        DONE: begin
            bcd_out = bcd_reg[11:8];
            bcd_valid = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule

module ooo_completion_detector (
    input logic clk,
    input logic rst_n,
    input logic [3:0] transaction_id,
    input logic start_transaction,
    input logic complete_transaction,
    input logic [3:0] complete_id,
    output logic [3:0] next_expected_id,
    output logic all_complete,
    output logic [15:0] completion_vector,
    output logic out_of_order_detected
);

typedef enum logic [2:0] {
    RESET,
    TRACKING,
    REORDER_BUFFER,
    FLUSH,
    COMPLETE,
    ERROR
} state_t;

state_t state, next_state;
logic [3:0] expected_id;
logic [3:0] head_ptr;
logic [3:0] tail_ptr;
logic [15:0] completion_mask;
logic [3:0] reorder_buffer [0:15];
logic [3:0] buffer_count;
logic [3:0] outstanding_count;
logic [7:0] timeout_counter;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= RESET;
        expected_id <= 4'b0;
        head_ptr <= 4'b0;
        tail_ptr <= 4'b0;
        completion_mask <= 16'b0;
        buffer_count <= 4'b0;
        outstanding_count <= 4'b0;
    end else begin
        state <= next_state;

        // Update completion tracking
        if (complete_transaction) begin
            completion_mask[complete_id] <= 1'b1;

            // Store in reorder buffer if out of order
            if (complete_id != expected_id) begin
                reorder_buffer[tail_ptr] <= complete_id;
                tail_ptr <= tail_ptr + 1;
                buffer_count <= buffer_count + 1;
                out_of_order_detected <= 1'b1;
            end
        end

        // Update expected ID when completing in order
        if (complete_transaction && complete_id == expected_id) begin
            expected_id <= expected_id + 1;

            // Check reorder buffer for next expected
            for (int i = 0; i < 16; i++) begin
                if (reorder_buffer[i] == expected_id + 1) begin
                    expected_id <= expected_id + 1;
                    // Remove from buffer
                    reorder_buffer[i] <= 4'b1111;
                    buffer_count <= buffer_count - 1;
                end
            end
        end

        // Update outstanding count
        if (start_transaction && !complete_transaction)
            outstanding_count <= outstanding_count + 1;
        else if (!start_transaction && complete_transaction)
            outstanding_count <= outstanding_count - 1;

        // Timeout counter
        if (state == TRACKING && outstanding_count > 0)
            timeout_counter <= timeout_counter + 1;
        else
            timeout_counter <= 8'b0;
    end
end

always_comb begin
    next_state = state;
    next_expected_id = expected_id;
    all_complete = (completion_mask == 16'hFFFF);
    completion_vector = completion_mask;
    out_of_order_detected = 1'b0;

    // Reorder buffer management
    logic [3:0] buffer_empty;
    logic [3:0] buffer_full;

    buffer_empty = (buffer_count == 0);
    buffer_full = (buffer_count == 16);

    case (state)
        RESET: begin
            next_expected_id = 4'b0;
            completion_vector = 16'b0;

            if (!rst_n)
                next_state = RESET;
            else
                next_state = TRACKING;
        end

        TRACKING: begin
            // Check for out-of-order completion
            if (complete_transaction && complete_id > expected_id) begin
                out_of_order_detected = 1'b1;

                if (buffer_full)
                    next_state = FLUSH;
                else
                    next_state = REORDER_BUFFER;
            end

            // Check for timeout
            if (timeout_counter > 100 && outstanding_count > 0) begin
                next_state = FLUSH;
            end

            // All transactions complete
            if (all_complete)
                next_state = COMPLETE;

            // Error detection
            if (complete_transaction && complete_id < expected_id)
                next_state = ERROR;
        end

        REORDER_BUFFER: begin
            // Process reorder buffer
            for (int i = 0; i < 16; i++) begin
                if (reorder_buffer[i] == expected_id) begin
                    next_expected_id = expected_id + 1;
                    // Continue checking for consecutive IDs
                    while (completion_mask[next_expected_id])
                        next_expected_id = next_expected_id + 1;
                end
            end

            if (buffer_empty)
                next_state = TRACKING;
        end

        FLUSH: begin
            // Force completion of all pending transactions
            next_expected_id = 4'b0;
            completion_vector = 16'hFFFF;

module runt_pulse_detector (
    input logic clk,
    input logic rst_n,
    input logic signal_in,
    input logic [3:0] min_width,
    output logic runt_detected
);

typedef enum logic [2:0] {IDLE, PULSE_LOW, PULSE_HIGH, CHECK} state_t;
state_t state, next_state;
logic [3:0] pulse_width;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        pulse_width <= 4'b0;
    end else begin
        state <= next_state;
        if (state == PULSE_LOW || state == PULSE_HIGH)
            pulse_width <= pulse_width + 1;
        else
            pulse_width <= 4'b0;
    end
end

always_comb begin
    next_state = state;
    runt_detected = 1'b0;

    case (state)
        IDLE: begin
            if (signal_in)
                next_state = PULSE_HIGH;
            else
                next_state = PULSE_LOW;
        end

        PULSE_HIGH: begin
            if (!signal_in) begin
                next_state = CHECK;
                // Check if pulse was too short
                if (pulse_width < min_width)
                    runt_detected = 1'b1;  // Immediate detection
            end
        end

        PULSE_LOW: begin
            if (signal_in) begin
                next_state = CHECK;
                // Check if pulse was too short
                if (pulse_width < min_width)
                    runt_detected = 1'b1;  // Immediate detection
            end
        end

        CHECK: begin
            // Return to IDLE after one cycle
            next_state = IDLE;
        end
    endcase
end

endmodule

module tcp_congestion_control (
    input logic clk,
    input logic rst_n,
    input logic ack_received,
    input logic timeout_event,
    input logic [15:0] rtt_measurement,
    input logic [2:0] duplicate_acks,
    output logic [15:0] congestion_window,
    output logic [15:0] slow_start_threshold,
    output logic [1:0] phase  // 00: SLOW_START, 01: CONG_AVOID, 10: FAST_RECOVERY
);

typedef enum logic [2:0] {
    SLOW_START,
    CONGESTION_AVOIDANCE,
    FAST_RECOVERY,
    FAST_RETRANSMIT,
    TIMEOUT_WAIT,
    PROBE
} state_t;

state_t state, next_state;
logic [15:0] cwnd;  // Congestion window
logic [15:0] ssthresh;  // Slow start threshold
logic [15:0] flight_size;
logic [3:0] ack_counter;
logic [31:0] rto_counter;
logic [15:0] min_rtt;
logic [15:0] avg_rtt;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= SLOW_START;
        cwnd <= 16'd1;
        ssthresh <= 16'd65535;
        ack_counter <= 4'b0;
        min_rtt <= 16'hFFFF;
        avg_rtt <= 16'd100;
    end else begin
        state <= next_state;

        // Update RTT measurements
        if (rtt_measurement < min_rtt)
            min_rtt <= rtt_measurement;

        avg_rtt <= (avg_rtt * 7 + rtt_measurement) >> 3;

        // Update window based on state
        unique case (state)
            SLOW_START: begin
                if (ack_received) begin
                    cwnd <= cwnd + 1;  // Exponential growth
                    ack_counter <= ack_counter + 1;

                    if (cwnd >= ssthresh)
                        next_state = CONGESTION_AVOIDANCE;
                end
            end

            CONGESTION_AVOIDANCE: begin
                if (ack_received) begin
                    ack_counter <= ack_counter + 1;
                    if (ack_counter == cwnd) begin
                        cwnd <= cwnd + 1;  // Linear growth
                        ack_counter <= 4'b0;
                    end
                end
            end

            FAST_RECOVERY: begin
                if (duplicate_acks == 3'd3) begin
                    next_state = FAST_RETRANSMIT;
                    ssthresh <= cwnd >> 1;
                    cwnd <= ssthresh + 3;
                end
            end
        endcase

        // Timeout handling
        if (timeout_event) begin
            ssthresh <= cwnd >> 1;
            cwnd <= 16'd1;
            next_state = TIMEOUT_WAIT;
            rto_counter <= 32'b0;
        end
    end
end

always_comb begin
    next_state = state;
    congestion_window = cwnd;
    slow_start_threshold = ssthresh;
    phase = 2'b00;

    // Flight size estimation
    flight_size = congestion_window >> 1;

    case (state)
        SLOW_START: begin
            phase = 2'b00;

            // Check for packet loss
            if (duplicate_acks >= 3'd3) begin
                next_state = FAST_RECOVERY;
                ssthresh = cwnd >> 1;
            end

            // RTT-based adaptation
            if (rtt_measurement > (avg_rtt + (avg_rtt >> 2))) begin
                // RTT increasing, prepare for congestion
                ssthresh = cwnd;
                next_state = CONGESTION_AVOIDANCE;
            end
        end

        CONGESTION_AVOIDANCE: begin
            phase = 2'b01;

            if (duplicate_acks == 3'd3) begin
                next_state = FAST_RETRANSMIT;
                ssthresh = cwnd >> 1;
                cwnd = ssthresh + 3;
            end

            // AIMD (Additive Increase Multiplicative Decrease)
            if (timeout_event) begin
                ssthresh = cwnd >> 1;
                cwnd = 16'd1;
                next_state = TIMEOUT_WAIT;
            end
        end

        FAST_RECOVERY: begin
            phase = 2'b10;

            if (ack_received) begin
                cwnd = ssthresh;
                next_state = CONGESTION_AVOIDANCE;
            end
        end

        FAST_RETRANSMIT: begin
            phase = 2'b10;

            // Retransmit lost packet
            if (ack_received) begin
                next_state = FAST_RECOVERY;
            end
        end

        TIMEOUT_WAIT: begin
            phase = 2'b00;

            rto_counter = rto_counter + 1;
            if (rto_counter > (min_rtt * 2)) begin
                if (ack_received)
                    next_state = SLOW_START;
                else
                    next_state = PROBE;
            end
        end

        PROBE: begin
            phase = 2'b00;

            // Send probe packets
            cwnd = 16'd1;
            if (ack_received)
                next_state = SLOW_START;
        end
    endcase
end

endmodule

module spi_master_mealy (
    input logic clk,
    input logic rst_n,
    input logic start,
    input logic [7:0] tx_data,
    output logic sclk,
    output logic mosi,
    input logic miso,
    output logic [7:0] rx_data,
    output logic busy,
    output logic done
);

typedef enum logic [2:0] {IDLE, ASSERT_CS, CLK_LOW, CLK_HIGH, DONE_ST} state_t;
state_t state, next_state;
logic [2:0] bit_count;
logic [7:0] shift_reg;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        bit_count <= 3'b0;
        shift_reg <= 8'b0;
    end else begin
        state <= next_state;
        if (state == CLK_LOW) begin
            shift_reg <= {shift_reg[6:0], miso};  // Sample on rising edge
            bit_count <= bit_count + 1;
        end
    end
end

always_comb begin
    next_state = state;
    sclk = 1'b0;
    mosi = 1'b0;
    busy = 1'b1;
    done = 1'b0;
    rx_data = shift_reg;

    case (state)
        IDLE: begin
            busy = 1'b0;
            if (start) begin
                next_state = ASSERT_CS;
                shift_reg = tx_data;
                bit_count = 3'b0;
            end
        end

        ASSERT_CS: begin
            next_state = CLK_LOW;  // Immediate transition
        end

        CLK_LOW: begin
            sclk = 1'b0;
            mosi = shift_reg[7];  // Output MSB first
            if (bit_count == 3'b111)  // Last bit
                next_state = DONE_ST;
            else
                next_state = CLK_HIGH;
        end

        CLK_HIGH: begin
            sclk = 1'b1;
            mosi = shift_reg[7];
            next_state = CLK_LOW;  // Immediate transition back
        end

        DONE_ST: begin
            done = 1'b1;  // Done signal
            next_state = IDLE;
        end
    endcase
end

endmodule

module fifo_monitor_mealy (
    input logic clk,
    input logic rst_n,
    input logic write_en,
    input logic read_en,
    input logic [3:0] fifo_depth,
    output logic almost_full,
    output logic almost_empty,
    output logic [3:0] fill_level
);

typedef enum logic [1:0] {NORMAL, WARN_FULL, WARN_EMPTY} state_t;
state_t state, next_state;
logic [3:0] count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= NORMAL;
        count <= 4'b0;
    end else begin
        state <= next_state;
        // Update count
        case ({write_en, read_en})
            2'b10: if (count < fifo_depth) count <= count + 1;
            2'b01: if (count > 0) count <= count - 1;
            default: count <= count;
        endcase
    end
end

assign fill_level = count;

always_comb begin
    next_state = state;
    almost_full = 1'b0;
    almost_empty = 1'b0;

    case (state)
        NORMAL: begin
            if (count >= fifo_depth - 2 && write_en) begin
                next_state = WARN_FULL;
                almost_full = 1'b1;  // Immediate warning on write
            end
            else if (count <= 2 && read_en) begin
                next_state = WARN_EMPTY;
                almost_empty = 1'b1;  // Immediate warning on read
            end
        end

        WARN_FULL: begin
            almost_full = 1'b1;
            if (count <= fifo_depth - 4 || (read_en && !write_en))
                next_state = NORMAL;
            else if (write_en && count == fifo_depth)
                almost_full = 1'b1;  // Stay in warning
        end

        WARN_EMPTY: begin
            almost_empty = 1'b1;
            if (count >= 4 || (write_en && !read_en))
                next_state = NORMAL;
            else if (read_en && count == 0)
                almost_empty = 1'b1;  // Stay in warning
        end
    endcase
end

endmodule

module crc_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic data_in,
    input logic data_valid,
    input logic crc_enable,
    output logic [7:0] crc_out,
    output logic crc_ready
);

typedef enum logic [1:0] {IDLE, PROCESS, FINAL} state_t;
state_t state, next_state;
logic [7:0] crc_reg;
logic [3:0] bit_count;

// CRC-8 polynomial: x^8 + x^2 + x + 1 (0x07)
parameter POLY = 8'h07;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        crc_reg <= 8'hFF;  // Initial value
        bit_count <= 4'b0;
    end else begin
        state <= next_state;
        if (state == PROCESS) begin
            crc_reg <= crc_next;
            bit_count <= bit_count + 1;
        end
    end
end

always_comb begin
    logic [7:0] crc_next;
    next_state = state;
    crc_out = crc_reg;
    crc_ready = 1'b0;

    // CRC computation
    crc_next = crc_reg;
    if (data_valid) begin
        crc_next[0] = crc_reg[7] ^ data_in;
        crc_next[1] = crc_reg[0] ^ crc_reg[7] ^ data_in;
        crc_next[2] = crc_reg[1] ^ crc_reg[7] ^ data_in;
        crc_next[3] = crc_reg[2];
        crc_next[4] = crc_reg[3];
        crc_next[5] = crc_reg[4];
        crc_next[6] = crc_reg[5];
        crc_next[7] = crc_reg[6];
    end

    case (state)
        IDLE: begin
            if (crc_enable) begin
                next_state = PROCESS;
                bit_count = 4'b0;
                crc_reg = 8'hFF;
            end
        end

        PROCESS: begin
            if (bit_count == 4'b1000) begin  // 8 bits processed
                next_state = FINAL;
                crc_ready = 1'b1;  // CRC ready immediately
                crc_out = crc_reg;
            end
        end

        FINAL: begin
            crc_ready = 1'b1;
            crc_out = crc_reg;
            if (!crc_enable)
                next_state = IDLE;
        end
    endcase
end

endmodule

module nn_activation_function (
    input logic clk,
    input logic rst_n,
    input logic signed [15:0] x_input,  // Q8.8 format
    input logic [1:0] func_select,      // 00: ReLU, 01: Tanh, 10: Sigmoid, 11: LeakyReLU
    input logic valid_in,
    output logic signed [15:0] y_output, // Q8.8 format
    output logic valid_out,
    output logic [3:0] region_detected
);

typedef enum logic [3:0] {
    IDLE,
    DETECT_REGION,
    COMPUTE_PIECEWISE_0,
    COMPUTE_PIECEWISE_1,
    COMPUTE_PIECEWISE_2,
    COMPUTE_PIECEWISE_3,
    COMPUTE_PIECEWISE_4,
    COMPUTE_PIECEWISE_5,
    SATURATE,
    OUTPUT,
    ERROR
} state_t;

state_t state, next_state;
logic signed [15:0] x_abs;
logic signed [31:0] accumulator;
logic [3:0] region;
logic [2:0] piecewise_count;

// Piecewise approximation coefficients for Tanh (Q4.12 format)
parameter signed [15:0] TANH_COEFF_0 = 16'h1000;  // 1.0 in Q4.12
parameter signed [15:0] TANH_COEFF_1 = 16'h0E00;  // 0.875
parameter signed [15:0] TANH_COEFF_2 = 16'h0C00;  // 0.75
parameter signed [15:0] TANH_COEFF_3 = 16'h0800;  // 0.5
parameter signed [15:0] TANH_COEFF_4 = 16'h0400;  // 0.25
parameter signed [15:0] TANH_COEFF_5 = 16'h0000;  // 0.0

// Region boundaries (Q8.8 format)
parameter signed [15:0] BOUNDARY_0 = 16'h0100;  // 1.0
parameter signed [15:0] BOUNDARY_1 = 16'h0200;  // 2.0
parameter signed [15:0] BOUNDARY_2 = 16'h0300;  // 3.0
parameter signed [15:0] BOUNDARY_3 = 16'h0400;  // 4.0
parameter signed [15:0] BOUNDARY_4 = 16'h0500;  // 5.0

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        x_abs <= 16'b0;
        accumulator <= 32'b0;
        region <= 4'b0;
        piecewise_count <= 3'b0;
    end else begin
        state <= next_state;

        if (state == DETECT_REGION) begin
            x_abs <= (x_input[15]) ? -x_input : x_input;
        end

        if (state == COMPUTE_PIECEWISE_0) begin
            unique case (func_select)
                2'b00: accumulator <= x_input;  // ReLU
                2'b01: begin  // Tanh approximation
                    case (region)
                        0: accumulator <= (x_input * TANH_COEFF_0) >>> 4;
                        1: accumulator <= (x_input * TANH_COEFF_1) >>> 4;
                        2: accumulator <= (x_input * TANH_COEFF_2) >>> 4;
                        3: accumulator <= (x_input * TANH_COEFF_3) >>> 4;
                        4: accumulator <= (x_input * TANH_COEFF_4) >>> 4;
                        default: accumulator <= (x_input * TANH_COEFF_5) >>> 4;
                    endcase
                end
                2'b10: begin  // Sigmoid approximation (1/(1+exp(-x)))
                    // Symmetric property: sigmoid(-x) = 1 - sigmoid(x)
                    if (x_input[15])
                        accumulator <= 32'h10000 - ((x_abs * TANH_COEFF_0) >>> 4);
                    else
                        accumulator <= ((x_abs * TANH_COEFF_0) >>> 4) + 32'h8000;
                end
                2'b11: begin  // LeakyReLU
                    if (x_input[15])
                        accumulator <= (x_input * 16'h0100) >>> 8;  // alpha = 0.0625
                    else
                        accumulator <= x_input;
                end
            endcase
            piecewise_count <= piecewise_count + 1;
        end
    end
end

always_comb begin
    next_state = state;
    y_output = accumulator[23:8];  // Convert back to Q8.8
    valid_out = 1'b0;
    region_detected = region;

    // Region detection logic
    logic [3:0] detected_region;
    detected_region = 4'b0;

    if (x_abs > BOUNDARY_4)
        detected_region = 4'd5;
    else if (x_abs > BOUNDARY_3)
        detected_region = 4'd4;
    else if (x_abs > BOUNDARY_2)
        detected_region = 4'd3;
    else if (x_abs > BOUNDARY_1)
        detected_region = 4'd2;
    else if (x_abs > BOUNDARY_0)
        detected_region = 4'd1;
    else
        detected_region = 4'd0;

    case (state)
        IDLE: begin
            if (valid_in) begin
                next_state = DETECT_REGION;
                region = detected_region;
            end
        end

        DETECT_REGION: begin
            next_state = COMPUTE_PIECEWISE_0;
            piecewise_count = 3'b0;
        end

        COMPUTE_PIECEWISE_0: begin
            next_state = COMPUTE_PIECEWISE_1;

            // Check for saturation
            if (func_select == 2'b00 && x_input[15] == 1'b0 && $signed(accumulator) < 0)
                next_state = SATURATE;
        end

        COMPUTE_PIECEWISE_1: begin
            next_state = COMPUTE_PIECEWISE_2;

            // Additional piecewise refinement for better accuracy
            if (func_select == 2'b01 && region > 2) begin
                // Second-order correction for high input values
                accumulator = accumulator - ((x_abs * 16'h0020) >>> 8);
            end
        end

        COMPUTE_PIECEWISE_2: begin
            next_state = COMPUTE_PIECEWISE_3;
        end

        COMPUTE_PIECEWISE_3: begin
            next_state = COMPUTE_PIECEWISE_4;
        end

        COMPUTE_PIECEWISE_4: begin
            next_state = COMPUTE_PIECEWISE_5;
        end

        COMPUTE_PIECEWISE_5: begin
            next_state = SATURATE;
        end

        SATURATE: begin
            // Apply saturation for Tanh and Sigmoid
            if (func_select != 2'b00) begin
                if (accumulator > 32'h00FFFFFF)
                    accumulator = 32'h00FFFFFF;
                else if (accumulator < -32'h00FFFFFF)
                    accumulator = -32'h00FFFFFF;
            end

            // Apply symmetry for odd functions
            if (func_select == 2'b01 && x_input[15])  // Tanh is odd
                accumulator = -accumulator;

            next_state = OUTPUT;
        end

        OUTPUT: begin
            valid_out = 1'b1;
            next_state = IDLE;
        end

        ERROR: begin
            y_output = 16'h7FFF;  // Max positive value on error
            valid_out = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule

module baud_rate_gen_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] divisor,
    input logic [3:0] fraction,
    output logic baud_tick
);

typedef enum logic [1:0] {IDLE, COUNT, ADJUST} state_t;
state_t state, next_state;
logic [7:0] counter;
logic [3:0] frac_acc;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        counter <= 8'b0;
        frac_acc <= 4'b0;
    end else begin
        state <= next_state;
        if (state == COUNT) begin
            counter <= counter + 1;
            if (counter == divisor - 1)
                counter <= 8'b0;
        end
        if (state == ADJUST)
            frac_acc <= frac_acc + fraction;
    end
end

always_comb begin
    next_state = state;
    baud_tick = 1'b0;

    case (state)
        IDLE: if (divisor != 0)
            next_state = COUNT;

        COUNT: begin
            if (counter == divisor - 1) begin
                if (frac_acc + fraction >= 16) begin
                    next_state = ADJUST;
                    baud_tick = 1'b1;  // Generate tick with fraction adjust
                end else begin
                    next_state = IDLE;
                    baud_tick = 1'b1;
                end
            end
        end

        ADJUST: begin
            next_state = IDLE;
            baud_tick = 1'b1;  // Extra tick for fractional adjustment
        end
    endcase
end

endmodule

module seq_detector_101_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [1:0] {S0, S1, S2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: if (din) begin
            next_state = S1;
        end else begin
            next_state = S0;
        end

        S1: if (din) begin
            next_state = S1;
        end else begin
            next_state = S2;
        end

        S2: if (din) begin
            next_state = S1;
            detected = 1'b1;  // Sequence "101" detected
        end else begin
            next_state = S0;
        end
    endcase
end

endmodule

module pattern_detector_1101 (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic match
);

typedef enum logic [2:0] {S0, S1, S11, S110} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    match = 1'b0;

    case (state)
        S0: next_state = din ? S1 : S0;

        S1: begin
            if (din) next_state = S11;
            else next_state = S0;
        end

        S11: begin
            if (din) next_state = S11;  // Overlap case
            else next_state = S110;
        end

        S110: begin
            if (din) begin
                next_state = S1;  // Last '1' can start new sequence
                match = 1'b1;     // Pattern "1101" detected
            end
            else next_state = S0;
        end
    endcase
end

endmodule

module adaptive_baud_detector (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    output logic baud_locked,
    output logic [19:0] measured_baud_period,
    output logic data_ready
);

typedef enum logic [3:0] {
    IDLE,
    WAIT_FOR_START,
    MEASURE_START,
    MEASURE_BIT0,
    MEASURE_BIT1,
    MEASURE_BIT2,
    VERIFY,
    LOCKED,
    ERROR
} state_t;

state_t state, next_state;
logic [19:0] period_counter;
logic [19:0] accumulated_period;
logic [2:0] bit_sample_count;
logic [19:0] bit_periods [0:7];
logic [3:0] measurement_index;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        period_counter <= 20'b0;
        accumulated_period <= 20'b0;
        bit_sample_count <= 3'b0;
        measurement_index <= 4'b0;
    end else begin
        state <= next_state;

        // Counter logic based on state
        unique case (state)
            IDLE: period_counter <= 20'b0;

            WAIT_FOR_START: begin
                if (!rx_line)  // Start bit detected
                    period_counter <= period_counter + 1;
                else
                    period_counter <= 20'b0;
            end

            MEASURE_START: begin
                if (!rx_line)
                    period_counter <= period_counter + 1;
            end

            MEASURE_BIT0, MEASURE_BIT1, MEASURE_BIT2: begin
                period_counter <= period_counter + 1;
                if (measurement_index < 8 && rx_line != (state == MEASURE_BIT0)) begin
                    bit_periods[measurement_index] <= period_counter;
                    measurement_index <= measurement_index + 1;
                end
            end

            VERIFY: begin
                accumulated_period <= (bit_periods[0] + bit_periods[1] +
                                      bit_periods[2] + bit_periods[3]) >> 2;
            end
        endcase
    end
end

always_comb begin
    next_state = state;
    baud_locked = 1'b0;
    data_ready = 1'b0;
    measured_baud_period = accumulated_period;

    // Statistical analysis variables
    logic [19:0] avg_period;
    logic [19:0] deviation;

    avg_period = (bit_periods[0] + bit_periods[1] + bit_periods[2] +
                  bit_periods[3] + bit_periods[4] + bit_periods[5] +
                  bit_periods[6] + bit_periods[7]) >> 3;

    deviation = 0;
    for (int i = 0; i < 8; i++) begin
        if (bit_periods[i] > avg_period)
            deviation = deviation + (bit_periods[i] - avg_period);
        else
            deviation = deviation + (avg_period - bit_periods[i]);
    end
    deviation = deviation >> 3;

    case (state)
        IDLE: begin
            if (!rx_line)
                next_state = WAIT_FOR_START;
        end

        WAIT_FOR_START: begin
            if (rx_line) begin
                if (period_counter > 100)  // Valid start bit length
                    next_state = MEASURE_START;
                else
                    next_state = ERROR;  // Glitch detected
            end
        end

        MEASURE_START: begin
            if (rx_line) begin
                bit_periods[0] = period_counter;
                measurement_index = 4'b1;
                next_state = MEASURE_BIT0;
                period_counter = 20'b0;
            end
        end

        MEASURE_BIT0, MEASURE_BIT1, MEASURE_BIT2: begin
            if (rx_line != (state == MEASURE_BIT0)) begin
                if (measurement_index < 8) begin
                    bit_periods[measurement_index] = period_counter;
                    period_counter = 20'b0;

                    if (measurement_index == 7)
                        next_state = VERIFY;
                end
            end

            // Timeout detection
            if (period_counter > avg_period * 2 && avg_period != 0)
                next_state = ERROR;
        end

        VERIFY: begin
            // Check if measurements are consistent (low deviation)
            if (deviation < (avg_period >> 3)) begin  // Within 12.5% tolerance
                next_state = LOCKED;
                measured_baud_period = avg_period;
                baud_locked = 1'b1;  // Lock immediately
                data_ready = 1'b1;
            end else begin
                next_state = ERROR;
            end
        end

        LOCKED: begin
            baud_locked = 1'b1;
            measured_baud_period = avg_period;

            // Monitor for baud rate changes
            if (!rx_line && period_counter > measured_baud_period * 3/2)
                next_state = IDLE;  // Re-detect if new start bit with different timing
        end

        ERROR: begin
            // Reset after error
            if (rx_line)
                next_state = IDLE;
        end
    endcase
end

endmodule

module pwm_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] period,
    input logic [7:0] duty_cycle,
    input logic update_duty,
    output logic pwm_out
);

typedef enum logic [1:0] {HIGH, LOW, UPDATE} state_t;
state_t state, next_state;
logic [7:0] counter;
logic [7:0] current_duty;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= LOW;
        counter <= 8'b0;
        current_duty <= 8'b0;
    end else begin
        state <= next_state;
        counter <= counter + 1;
        if (update_duty)
            current_duty <= duty_cycle;
    end
end

always_comb begin
    next_state = state;
    pwm_out = 1'b0;

    case (state)
        HIGH: begin
            pwm_out = 1'b1;
            if (counter == current_duty - 1) begin
                next_state = LOW;
                pwm_out = 1'b0;  // Immediate transition
            end
            if (update_duty && counter < duty_cycle)
                pwm_out = 1'b1;  // Immediate duty cycle update
        end

        LOW: begin
            pwm_out = 1'b0;
            if (counter == period - 1) begin
                next_state = HIGH;
                counter = 8'b0;
                pwm_out = 1'b1;  // Immediate transition
            end
            if (update_duty && duty_cycle > 0)
                next_state = UPDATE;  // Special update state
        end

        UPDATE: begin
            pwm_out = 1'b1;  // Immediate response to new duty cycle
            next_state = HIGH;
            counter = 8'b0;
        end
    endcase
end

endmodule

module vending_machine_mealy (
    input logic clk,
    input logic rst_n,
    input logic coin_25,  // Quarter
    input logic coin_10,  // Dime
    output logic dispense
);

typedef enum logic [1:0] {S0, S25, S35} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    dispense = 1'b0;

    case (state)
        S0: begin
            if (coin_25) next_state = S25;
            else if (coin_10) next_state = S10;
        end

        S10: begin
            if (coin_25) begin
                next_state = S35;
                dispense = 1'b1;  // Total = 35 cents - dispense
            end
            else if (coin_10) next_state = S20;
        end

        S20: begin
            if (coin_25) begin
                next_state = S45;
                dispense = 1'b1;  // Total = 45 cents - dispense with change
            end
            else if (coin_10) next_state = S30;
        end

        S25: begin
            if (coin_10) begin
                next_state = S35;
                dispense = 1'b1;  // Total = 35 cents - dispense
            end
        end

        S30, S35, S45: begin
            // After dispense, go back to S0
            next_state = S0;
        end
    endcase
end

endmodule

module seq_detector_1001_nonoverlap (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [2:0] {S0, S1, S10, S100} state_t;
state_t state, next_state;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: next_state = din ? S1 : S0;

        S1: next_state = din ? S1 : S10;

        S10: next_state = din ? S1 : S100;

        S100: begin
            if (din) begin
                next_state = S1;  // Start new sequence from last '1'
                detected = 1'b1;  // Pattern "1001" detected
            end else begin
                next_state = S0;   // Reset if next bit is 0
            end
        end
    endcase
end

endmodule

module uart_sampler_mealy (
    input logic clk,
    input logic rst_n,
    input logic rx_line,
    input logic sample_enable,
    output logic bit_value,
    output logic bit_ready
);

typedef enum logic [2:0] {IDLE, START, MIDDLE, SAMPLE} state_t;
state_t state, next_state;
logic [2:0] oversample_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        oversample_count <= 3'b0;
    end else begin
        state <= next_state;
        if (sample_enable)
            oversample_count <= oversample_count + 1;
    end
end

always_comb begin
    next_state = state;
    bit_value = 1'b0;
    bit_ready = 1'b0;

    case (state)
        IDLE: begin
            if (!rx_line && sample_enable)  // Start bit detected
                next_state = START;
        end

        START: begin
            if (sample_enable) begin
                if (oversample_count == 3'b100) begin  // Middle of start bit
                    next_state = MIDDLE;
                end
            end
        end

        MIDDLE: begin
            if (sample_enable) begin
                if (oversample_count == 3'b111) begin  // Sample point
                    next_state = SAMPLE;
                    bit_value = rx_line;  // Sample the bit
                    bit_ready = 1'b1;     // Bit ready immediately
                end
            end
        end

        SAMPLE: begin
            if (sample_enable) begin
                if (oversample_count == 3'b111)
                    next_state = IDLE;
                else
                    next_state = MIDDLE;
            end
        end
    endcase
end

endmodule

module jpeg_huffman_encoder (
    input logic clk,
    input logic rst_n,
    input logic [7:0] data_byte,           // Input data byte
    input logic [5:0] run_length,           // Run length of zeros
    input logic [3:0] category,              // Category of non-zero value
    input logic [11:0] amplitude,            // Amplitude of non-zero value
    input logic valid_in,
    input logic last_block,
    output logic [15:0] encoded_bits,        // Huffman encoded bits
    output logic [3:0] bit_length,           // Length of encoded bits (1-16)
    output logic [3:0] code_count,           // Number of codes generated
    output logic done,
    output logic eob_detected
);

typedef enum logic [3:0] {
    IDLE,
    GET_DC_DIFF,
    ENCODE_DC,
    GET_AC_COEFF,
    ENCODE_AC_RUN,
    ENCODE_AC_SIZE,
    ENCODE_AC_AMPLITUDE,
    CHECK_EOB,
    INSERT_EOB,
    FLUSH,
    COMPLETE,
    WAIT
} state_t;

state_t state, next_state;
logic [15:0] huffman_code;
logic [3:0] huffman_len;
logic [5:0] zero_run;
logic [3:0] size_category;
logic [11:0] value_amplitude;
logic [2:0] ac_counter;
logic [7:0] bit_buffer;
logic [3:0] bit_pos;
logic [3:0] code_counter;

// Huffman tables (simplified JPEG tables)
typedef struct {
    logic [15:0] code;
    logic [3:0] length;
} huffman_entry_t;

// DC Huffman table (luminance)
huffman_entry_t dc_table [0:11] = '{
    '{16'h0000, 4'd2},  // 00
    '{16'h0002, 4'd3},  // 010
    '{16'h0003, 4'd3},  // 011
    '{16'h0004, 4'd3},  // 100
    '{16'h0005, 4'd3},  // 101
    '{16'h0006, 4'd3},  // 110
    '{16'h000E, 4'd4},  // 1110
    '{16'h001E, 4'd5},  // 11110
    '{16'h003E, 4'd6},  // 111110
    '{16'h007E, 4'd7},  // 1111110
    '{16'h00FE, 4'd8},  // 11111110
    '{16'h01FE, 4'd9}   // 111111110
};

// AC Huffman table (luminance) - simplified
huffman_entry_t ac_table [0:255] = '{
    // Run/Size combinations
    '{16'h0000, 4'd4},  // EOB
    '{16'h0001, 4'd2},  // 0/1
    '{16'h0002, 4'd2},  // 0/2
    '{16'h0003, 4'd3},  // 0/3
    // ... more entries (simplified for example)
    default: '{16'hFFFF, 4'd16}
};

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        huffman_code <= 16'b0;
        huffman_len <= 4'b0;
        zero_run <= 6'b0;
        size_category <= 4'b0;
        value_amplitude <= 12'b0;
        ac_counter <= 3'b0;
        bit_buffer <= 8'b0;
        bit_pos <= 4'b0;
        code_counter <= 4'b0;
    end else begin
        state <= next_state;

        // Capture input data
        if (valid_in && state == IDLE) begin
            size_category <= category;
            zero_run <= run_length;
            value_amplitude <= amplitude;
        end

        // Update counters
        if (state == ENCODE_DC || state == ENCODE_AC_SIZE)
            code_counter <= code_counter + 1;

        if (state == ENCODE_AC_RUN)
            ac_counter <= ac_counter + 1;
    end
end

always_comb begin
    next_state = state;
    encoded_bits = huffman_code;
    bit_length = huffman_len;
    code_count = code_counter;
    done = 1'b0;
    eob_detected = 1'b0;

    // Huffman encoding logic
    logic [15:0] temp_code;
    logic [3:0] temp_len;
    logic [11:0] temp_amplitude;

    case (state)
        IDLE: begin
            code_counter = 4'b0;
            if (valid_in) begin
                next_state = GET_DC_DIFF;
            end
        end

        GET_DC_DIFF: begin
            // Get DC coefficient difference category
            if (size_category < 12) begin
                huffman_code = dc_table[size_category].code;
                huffman_len = dc_table[size_category].length;
                next_state = ENCODE_DC;
            end else begin
                next_state = WAIT;
            end
        end

        ENCODE_DC: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            // Append amplitude bits
            if (size_category > 0) begin
                temp_amplitude = value_amplitude;
                // Encode amplitude in lower bits
                encoded_bits = (huffman_code << size_category) |
                              (temp_amplitude & ((1 << size_category) - 1));
                bit_length = huffman_len + size_category;
            end

            next_state = GET_AC_COEFF;
            ac_counter = 3'b0;
        end

        GET_AC_COEFF: begin
            if (ac_counter < 8) begin  // Max 8 AC coefficients per block
                if (zero_run > 0) begin
                    // Encode run-length of zeros
                    next_state = ENCODE_AC_RUN;
                end else if (size_category > 0) begin
                    // Encode non-zero AC coefficient
                    next_state = ENCODE_AC_SIZE;
                end else begin
                    // Skip to next coefficient
                    ac_counter = ac_counter + 1;
                end
            end else begin
                next_state = CHECK_EOB;
            end
        end

        ENCODE_AC_RUN: begin
            // Encode run-length of zeros (simplified)
            temp_code = ac_table[zero_run * 16 + size_category].code;
            temp_len = ac_table[zero_run * 16 + size_category].length;

            if (temp_len > 0) begin
                huffman_code = temp_code;
                huffman_len = temp_len;
                next_state = ENCODE_AC_SIZE;
            end else begin
                // Use extended run-length encoding
                next_state = ENCODE_AC_SIZE;
            end
        end

        ENCODE_AC_SIZE: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            if (size_category > 0) begin
                // Encode amplitude for AC coefficient
                encoded_bits = (huffman_code << size_category) |
                              (value_amplitude & ((1 << size_category) - 1));
                bit_length = huffman_len + size_category;
            end

            next_state = ENCODE_AC_AMPLITUDE;
        end

        ENCODE_AC_AMPLITUDE: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            ac_counter = ac_counter + 1;
            next_state = GET_AC_COEFF;
        end

        CHECK_EOB: begin
            if (last_block) begin
                // Insert End-of-Block marker
                next_state = INSERT_EOB;
                eob_detected = 1'b1;
            end else begin
                next_state = COMPLETE;
            end
        end

        INSERT_EOB: begin
            // EOB code (0x00 with length 4 in simplified table)
            encoded_bits = ac_table[0].code;
            bit_length = ac_table[0].length;
            code_counter = code_counter + 1;
            next_state = FLUSH;
        end

        FLUSH: begin
            // Flush remaining bits
            if (bit_pos > 0) begin
                // Pad with zeros if necessary
                encoded_bits = bit_buffer;
                bit_length = bit_pos;
                bit_pos = 4'b0;
            end
            next_state = COMPLETE;
        end

        COMPLETE: begin
            done = 1'b1;
            next_state = IDLE;
        end

        WAIT: begin
            // Wait state for complex encoding
            next_state = ENCODE_DC;
        end
    endcase
end

endmodule

module ldpc_decoder_min_sum (
    input logic clk,
    input logic rst_n,
    input logic [5:0] llr_input [0:255],      // Log-likelihood ratios from channel
    input logic [7:0] code_length,
    input logic [3:0] iterations_max,
    input logic new_frame,
    output logic [5:0] llr_output [0:255],     // Updated LLRs after decoding
    output logic [0:255] decoded_bits,
    output logic [3:0] iteration_count,
    output logic converged,
    output logic decoding_done
);

typedef enum logic [4:0] {
    IDLE,
    INIT_VARIABLE_NODES,
    CHECK_NODE_UPDATE_0,
    CHECK_NODE_UPDATE_1,
    CHECK_NODE_UPDATE_2,
    CHECK_NODE_UPDATE_3,
    VARIABLE_NODE_UPDATE_0,
    VARIABLE_NODE_UPDATE_1,
    VARIABLE_NODE_UPDATE_2,
    VARIABLE_NODE_UPDATE_3,
    HARD_DECISION,
    PARITY_CHECK,
    EARLY_TERMINATE,
    ITERATION_DONE,
    FINAL_OUTPUT,
    MAX_ITERATIONS,
    DECODE_FAILED
} state_t;

state_t state, next_state;
logic [5:0] var_to_check [0:255][0:7];     // Messages: variable -> check nodes
logic [5:0] check_to_var [0:127][0:15];     // Messages: check -> variable nodes
logic [5:0] current_llr [0:255];
logic [0:255] hard_bits;
logic [7:0] check_node_idx;
logic [7:0] var_node_idx;
logic [7:0] neighbor_idx;
logic [3:0] iter;
logic [15:0] parity_sum;
logic converge_flag;
logic [7:0] check_degree [0:127];            // Degree of check nodes
logic [7:0] var_degree [0:255];               // Degree of variable nodes

// Tanner graph connections (simplified regular LDPC)
parameter CHECK_NODES = 128;
parameter VARIABLE_NODES = 256;
parameter DEGREE_VAR = 4;    // Regular: each variable node connects to 4 check nodes
parameter DEGREE_CHECK = 8;   // Regular: each check node connects to 8 variable nodes

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        iter <= 4'b0;
        check_node_idx <= 8'b0;
        var_node_idx <= 8'b0;
        neighbor_idx <= 8'b0;
        converge_flag <= 1'b0;
        parity_sum <= 16'b0;

        for (int i = 0; i < 256; i++) begin
            current_llr[i] <= 6'b0;
            hard_bits[i] <= 1'b0;
            for (int j = 0; j < 8; j++)
                var_to_check[i][j] <= 6'b0;
        end

        for (int i = 0; i < 128; i++)
            for (int j = 0; j < 16; j++)
                check_to_var[i][j] <= 6'b0;
    end else begin
        state <= next_state;

        // Initialize with channel LLRs
        if (state == INIT_VARIABLE_NODES && new_frame) begin
            for (int i = 0; i < 256; i++)
                current_llr[i] <= llr_input[i];
        end

        // Check node update (Min-Sum algorithm)
        if (state >= CHECK_NODE_UPDATE_0 && state <= CHECK_NODE_UPDATE_3) begin
            logic [5:0] min1, min2;
            logic [5:0] abs_val;
            logic [5:0] product;

            // Find two minimum magnitudes
            min1 = 6'h3F;  // Max value
            min2 = 6'h3F;

            for (int i = 0; i < 8; i++) begin
                abs_val = var_to_check[check_node_idx * 8 + i][neighbor_idx][5] ?
                          -var_to_check[check_node_idx * 8 + i][neighbor_idx] :
                          var_to_check[check_node_idx * 8 + i][neighbor_idx];

                if (abs_val < min1) begin
                    min2 = min1;
                    min1 = abs_val;
                end else if (abs_val < min2) begin
                    min2 = abs_val;
                end
            end

            // Update messages from check node to variable nodes
            for (int i = 0; i < 8; i++) begin
                abs_val = var_to_check[check_node_idx * 8 + i][neighbor_idx][5] ?
                          -var_to_check[check_node_idx * 8 + i][neighbor_idx] :
                          var_to_check[check_node_idx * 8 + i][neighbor_idx];

                product = 1'b1;
                for (int j = 0; j < 8; j++)
                    if (j != i)
                        product = product ^ var_to_check[check_node_idx * 8 + j][neighbor_idx][5];

                if (abs_val == min1)
                    check_to_var[check_node_idx][i] = product ? min2 : -min2;
                else
                    check_to_var[check_node_idx][i] = product ? min1 : -min1;
            end

            check_node_idx <= check_node_idx + 1;
            if (check_node_idx == CHECK_NODES - 1)
                check_node_idx <= 8'b0;
        end

        // Variable node update
        if (state >= VARIABLE_NODE_UPDATE_0 && state <= VARIABLE_NODE_UPDATE_3) begin
            logic [5:0] sum;

            for (int i = 0; i < 4; i++) begin
                sum = current_llr[var_node_idx];
                for (int j = 0; j < 4; j++)
                    if (j != i)
                        sum = sum + check_to_var[var_node_connections[var_node_idx][j]][var_node_idx];

                var_to_check[var_node_idx][i] = sum;
            end

            // Update total LLR
            current_llr[var_node_idx] = current_llr[var_node_idx];
            for (int j = 0; j < 4; j++)
                current_llr[var_node_idx] = current_llr[var_node_idx] +
                                           check_to_var[var_node_connections[var_node_idx][j]][var_node_idx];

            var_node_idx <= var_node_idx + 1;
            if (var_node_idx == VARIABLE_NODES - 1)
                var_node_idx <= 8'b0;
        end

        // Hard decision and parity check
        if (state == HARD_DECISION) begin
            for (int i = 0; i < 256; i++)
                hard_bits[i] <= current_llr[i][5] ? 1'b1 : 1'b0;  // Sign bit
        end

        if (state == PARITY_CHECK) begin
            // Check all parity equations
            converge_flag = 1'b1;
            for (int i = 0; i < CHECK_NODES; i++) begin
                parity_sum = 16'b0;
                for (int j = 0; j < 8; j++)
                    parity_sum = parity_sum ^ hard_bits[i * 8 + j];

                if (parity_sum != 0)
                    converge_flag = 1'b0;
            end

            if (converge_flag)
                iter <= iter + 1;
        end
    end
end

// Variable node to check node connections (simplified regular pattern)
function [7:0] var_node_connections [0:255][0:3];
    for (int i = 0; i < 256; i++)
        for (int j = 0; j < 4; j++)
            var_node_connections[i][j] = (i + j * 64) % 128;
endfunction

always_comb begin
    next_state = state;
    llr_output = current_llr;
    decoded_bits = hard_bits;
    iteration_count = iter;
    converged = converge_flag;
    decoding_done = 1'b0;

    case (state)
        IDLE: begin
            if (new_frame) begin
                next_state = INIT_VARIABLE_NODES;
                iter = 4'b0;
                converge_flag = 1'b0;
            end
        end

        INIT_VARIABLE_NODES: begin
            next_state = CHECK_NODE_UPDATE_0;
            check_node_idx = 8'b0;
        end

        CHECK_NODE_UPDATE_0: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_1;
        end

        CHECK_NODE_UPDATE_1: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_2;
        end

        CHECK_NODE_UPDATE_2: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_3;
        end

        CHECK_NODE_UPDATE_3: begin
            if (check_node_idx == CHECK_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_0;
            else
                next_state = CHECK_NODE_UPDATE_0;
        end

        VARIABLE_NODE_UPDATE_0: begin
            var_node_idx = 8'b0;
            next_state = VARIABLE_NODE_UPDATE_1;
        end

        VARIABLE_NODE_UPDATE_1: begin
            if (var_node_idx == VARIABLE_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_2;
            else
                next_state = VARIABLE_NODE_UPDATE_1;
        end

        VARIABLE_NODE_UPDATE_2: begin
            if (var_node_idx == VARIABLE_NODES - 1)
                next_state = VARIABLE_NODE_UPDATE_3;
            else
                next_state = VARIABLE_NODE_UPDATE_2;
        end

        VARIABLE_NODE_UPDATE_3: begin
            if (var_node_idx == VARIABLE_NODES - 1)
                next_state = HARD_DECISION;
            else
                next_state = VARIABLE_NODE_UPDATE_0;
        end

        HARD_DECISION: begin
            next_state = PARITY_CHECK;
        end

        PARITY_CHECK: begin
            if (converge_flag) begin
                next_state = EARLY_TERMINATE;
            end else begin
                if (iter < iterations_max - 1)
                    next_state = CHECK_NODE_UPDATE_0;
                else
                    next_state = MAX_ITERATIONS;
            end
        end

        EARLY_TERMINATE: begin
            decoding_done = 1'b1;
            next_state = FINAL_OUTPUT;
        end

        ITERATION_DONE: begin
            iter = iter + 1;
            if (iter < iterations_max)
                next_state = CHECK_NODE_UPDATE_0;
            else
                next_state = MAX_ITERATIONS;
        end

        MAX_ITERATIONS: begin
            decoding_done = 1'b1;
            next_state = FINAL_OUTPUT;
        end

        FINAL_OUTPUT: begin
            decoding_done = 1'b1;
            next_state = IDLE;
        end

        DECODE_FAILED: begin
            decoding_done = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule

module power_manager_advanced (
    input logic clk,
    input logic rst_n,
    input logic [15:0] activity_level,
    input logic [31:0] time_counter,
    input logic interrupt_req,
    output logic [1:0] power_state,  // 00: FULL, 01: SLEEP, 10: DEEP_SLEEP, 11: OFF
    output logic clock_gated,
    output logic voltage_scaled,
    output logic predictive_wake
);

typedef enum logic [2:0] {
    FULL_PERF,
    MONITOR_ACTIVITY,
    LIGHT_SLEEP,
    DEEP_SLEEP,
    PREDICTIVE_WAKE,
    WAKEUP_SEQ,
    POWER_OFF,
    EMERGENCY_WAKE
} state_t;

state_t state, next_state;
logic [31:0] idle_counter;
logic [15:0] activity_history [0:7];
logic [2:0] history_ptr;
logic [31:0] predicted_wake_time;
logic [3:0] wakeup_countdown;

// Power management parameters
parameter THRESHOLD_LOW = 16'h0100;
parameter THRESHOLD_HIGH = 16'h1000;
parameter IDLE_TIMEOUT = 32'h10000;
parameter DEEP_SLEEP_TIMEOUT = 32'h100000;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= FULL_PERF;
        idle_counter <= 32'b0;
        history_ptr <= 3'b0;
        wakeup_countdown <= 4'b0;
        for (int i = 0; i < 8; i++)
            activity_history[i] <= 16'b0;
    end else begin
        state <= next_state;

        // Update activity history
        if (state != POWER_OFF) begin
            activity_history[history_ptr] <= activity_level;
            history_ptr <= history_ptr + 1;
        end

        // Idle counter logic
        if (state == MONITOR_ACTIVITY && activity_level < THRESHOLD_LOW)
            idle_counter <= idle_counter + 1;
        else
            idle_counter <= 32'b0;

        // Wakeup countdown
        if (state == PREDICTIVE_WAKE)
            wakeup_countdown <= wakeup_countdown - 1;
    end
end

always_comb begin
    next_state = state;
    power_state = 2'b00;
    clock_gated = 1'b0;
    voltage_scaled = 1'b0;
    predictive_wake = 1'b0;

    // Activity prediction logic
    logic [19:0] activity_sum;
    logic [15:0] predicted_activity;
    logic pattern_detected;

    activity_sum = 0;
    for (int i = 0; i < 8; i++)
        activity_sum = activity_sum + activity_history[i];
    predicted_activity = activity_sum >> 3;

    // Detect activity patterns
    pattern_detected = (activity_history[0] > THRESHOLD_HIGH &&
                        activity_history[1] < THRESHOLD_LOW &&
                        activity_history[2] > THRESHOLD_HIGH);

    case (state)
        FULL_PERF: begin
            power_state = 2'b00;
            clock_gated = 1'b0;
            voltage_scaled = 1'b0;

            if (activity_level < THRESHOLD_LOW)
                next_state = MONITOR_ACTIVITY;
        end

        MONITOR_ACTIVITY: begin
            power_state = 2'b00;

            if (activity_level > THRESHOLD_HIGH) begin
                next_state = FULL_PERF;
            end else if (idle_counter > IDLE_TIMEOUT) begin
                next_state = LIGHT_SLEEP;
                clock_gated = 1'b1;  // Immediate clock gating
            end

            // Predictive pattern detection
            if (pattern_detected) begin
                predicted_wake_time = time_counter + 32'h1000;
                next_state = PREDICTIVE_WAKE;
            end
        end

        LIGHT_SLEEP: begin
            power_state = 2'b01;
            clock_gated = 1'b1;
            voltage_scaled = 1'b1;  // Scale voltage down

            if (interrupt_req) begin
                next_state = WAKEUP_SEQ;
            end else if (idle_counter > DEEP_SLEEP_TIMEOUT) begin
                next_state = DEEP_SLEEP;
            end

            // Predictive wake from pattern
            if (time_counter >= predicted_wake_time - 32'h100) begin
                next_state = PREDICTIVE_WAKE;
                predictive_wake = 1'b1;
            end
        end

        DEEP_SLEEP: begin
            power_state = 2'b10;
            clock_gated = 1'b1;
            voltage_scaled = 1'b1;

            if (interrupt_req) begin
                next_state = EMERGENCY_WAKE;
            end

            // Check if we should power off completely
            if (idle_counter > DEEP_SLEEP_TIMEOUT * 4) begin
                next_state = POWER_OFF;
            end
        end

        PREDICTIVE_WAKE: begin
            power_state = 2'b00;
            clock_gated = 1'b0;
            voltage_scaled = 1'b0;
            predictive_wake = 1'b1;

            wakeup_countdown = 4'd10;
            if (wakeup_countdown == 4'd0) begin
                if (activity_level > THRESHOLD_LOW)
                    next_state = FULL_PERF;
                else
                    next_state = LIGHT_SLEEP;
            end
        end

        WAKEUP_SEQ: begin
            power_state = 2'b00;
            // Stabilization sequence
            voltage_scaled = 1'b0;
            clock_gated = 1'b0;

            if (time_counter[3:0] == 4'b1111)  // Wait for stabilization
                next_state = FULL_PERF;
        end

        EMERGENCY_WAKE: begin
            power_state = 2'b00;
            // Fast wakeup for interrupts
            voltage_scaled = 1'b0;
            clock_gated = 1'b0;
            next_state = FULL_PERF;  // Immediate wake
        end

        POWER_OFF: begin
            power_state = 2'b11;
            clock_gated = 1'b1;
            voltage_scaled = 1'b1;

            // Wake on pin change or timer
            if (interrupt_req)
                next_state = EMERGENCY_WAKE;
        end
    endcase
end

endmodule

module manchester_encoder_mealy (
    input logic clk,
    input logic rst_n,
    input logic data_in,
    input logic data_valid,
    output logic encoded_out
);

typedef enum logic {WAIT, SEND_0, SEND_1} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= WAIT;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    encoded_out = 1'b0;

    case (state)
        WAIT: begin
            if (data_valid) begin
                if (data_in) begin
                    next_state = SEND_1;
                    encoded_out = 1'b1;  // Start with high for '1'
                end else begin
                    next_state = SEND_0;
                    encoded_out = 1'b0;  // Start with low for '0'
                end
            end
        end

        SEND_0: begin
            encoded_out = 1'b1;  // Transition to high in second half
            next_state = WAIT;    // Go back to wait after one bit
        end

        SEND_1: begin
            encoded_out = 1'b0;  // Transition to low in second half
            next_state = WAIT;    // Go back to wait after one bit
        end
    endcase
end

endmodule

module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STABLE0;
        counter <= 16'b0;
    end else begin
        state <= next_state;
        if (state == COUNT0 || state == COUNT1)
            counter <= counter + 1;
        else
            counter <= 16'b0;
    end
end

always_comb begin
    next_state = state;
    debounced_out = 1'b0;

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            if (noisy_in)
                next_state = COUNT0;
        end

        COUNT0: begin
            debounced_out = 1'b0;
            if (!noisy_in)
                next_state = STABLE0;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE1;
                debounced_out = 1'b1;  // Output high immediately
            end
        end

        STABLE1: begin
            debounced_out = 1'b1;
            if (!noisy_in)
                next_state = COUNT1;
        end

        COUNT1: begin
            debounced_out = 1'b1;
            if (noisy_in)
                next_state = STABLE1;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE0;
                debounced_out = 1'b0;  // Output low immediately
            end
        end
    endcase
end

endmodule

module adaptive_equalizer (
    input logic clk,
    input logic rst_n,
    input logic signed [11:0] rx_signal,      // Received distorted signal
    input logic signed [11:0] training_seq,   // Known training sequence
    input logic training_mode,
    input logic [2:0] convergence_speed,      // 0: slow, 7: fast
    output logic signed [11:0] eq_output,     // Equalized output
    output logic [15:0] snr_estimate,         // Signal-to-noise ratio estimate
    output logic locked
);

typedef enum logic [3:0] {
    RESET,
    ACQUIRE,
    TRAINING,
    COARSE_EQ,
    FINE_EQ,
    TRACKING,
    BLIND_MODE,
    RETRAIN,
    LOCKED_ST,
    UNLOCKED
} state_t;

state_t state, next_state;
logic signed [11:0] delay_line [0:15];  // Tapped delay line
logic signed [15:0] eq_coeffs [0:15];   // Equalizer coefficients (Q4.12)
logic signed [31:0] acc;
logic [3:0] tap_ptr;
logic [15:0] error_power;
logic [15:0] signal_power;
logic [7:0] lock_counter;
logic [3:0] training_index;
logic signed [31:0] error_signal;

// LMS parameters
logic [15:0] mu;  // Step size (Q4.12)
logic [15:0] leakage;  // Coefficient leakage factor

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= RESET;
        tap_ptr <= 4'b0;
        error_power <= 16'b0;
        signal_power <= 16'b0;
        lock_counter <= 8'b0;
        training_index <= 4'b0;

        for (int i = 0; i < 16; i++) begin
            delay_line[i] <= 12'b0;
            eq_coeffs[i] <= 16'b0;
        end
        // Center tap initialization
        eq_coeffs[8] <= 16'h1000;  // 1.0 in Q4.12
    end else begin
        state <= next_state;

        // Shift delay line
        delay_line[0] <= rx_signal;
        for (int i = 1; i < 16; i++)
            delay_line[i] <= delay_line[i-1];

        // Update coefficients based on state
        unique case (state)
            TRAINING, COARSE_EQ, FINE_EQ, TRACKING: begin
                // LMS coefficient update
                for (int i = 0; i < 16; i++) begin
                    if (training_mode) begin
                        // Leaky LMS to prevent coefficient drift
                        eq_coeffs[i] <= eq_coeffs[i] -
                                       ((eq_coeffs[i] * leakage) >>> 12) +
                                       ((error_signal[27:12] * delay_line[i] * mu) >>> 12);
                    end
                end
            end

            BLIND_MODE: begin
                // Constant modulus algorithm (CMA) for blind equalization
                for (int i = 0; i < 16; i++) begin
                    // CMA update: w(n+1) = w(n) + mu * e(n) * x(n) * conj(y(n))
                    // Simplified for BPSK/QPSK
                    eq_coeffs[i] <= eq_coeffs[i] +
                                   ((error_signal[27:12] * delay_line[i] * mu) >>> 12);
                end
            end
        endcase

        // Update power estimates
        signal_power <= signal_power +
                       (rx_signal * rx_signal) - (signal_power >>> 8);
        error_power <= error_power +
                      (error_signal[23:8] * error_signal[23:8]) - (error_power >>> 8);
    end
end

always_comb begin
    next_state = state;
    eq_output = 12'b0;
    snr_estimate = (signal_power * 16'h1000) / (error_power + 1);
    locked = (state == LOCKED_ST);

    // Compute equalizer output
    acc = 32'b0;
    for (int i = 0; i < 16; i++)
        acc = acc + (delay_line[i] * eq_coeffs[i]);
    eq_output = acc[23:12];  // Scale back to 12-bit

    // Error calculation
    if (training_mode)
        error_signal = (training_seq * 16'h1000) - acc;
    else
        error_signal = -acc;  // Decision-directed

    // Lock detection
    logic lock_detect;
    lock_detect = (error_power < (signal_power >>> 4));  // SNR > 12dB

    case (state)
        RESET: begin
            mu = 16'h0800;  // Initial step size
            leakage = 16'h0010;  // Small leakage
            next_state = ACQUIRE;
        end

        ACQUIRE: begin
            // Coarse signal acquisition
            if (signal_power > 16'h1000)
                next_state = TRAINING;
            else if (lock_counter > 100)
                next_state = UNLOCKED;
            else
                lock_counter <= lock_counter + 1;
        end

        TRAINING: begin
            mu = (convergence_speed << 8);  // Scale step size
            training_index <= training_index + 1;

            if (training_index == 4'd15) begin
                if (lock_detect)
                    next_state = COARSE_EQ;
                else
                    next_state = RETRAIN;
            end
        end

        COARSE_EQ: begin
            mu = 16'h0400;  // Medium step size

            if (lock_detect) begin
                lock_counter <= lock_counter + 1;
                if (lock_counter > 50)
                    next_state = FINE_EQ;
            end else begin
                lock_counter <= 8'b0;
                if (lock_counter > 200)
                    next_state = RETRAIN;
            end
        end

        FINE_EQ: begin
            mu = 16'h0200;  // Small step size for fine tuning

            if (lock_detect) begin
                lock_counter <= lock_counter + 1;
                if (lock_counter > 100)
                    next_state = LOCKED_ST;
            end else begin
                lock_counter <= 8'b0;
                next_state = COARSE_EQ;
            end
        end

        TRACKING: begin
            mu = 16'h0100;  // Very small step size for tracking

            if (!lock_detect && lock_counter > 20)
                next_state = BLIND_MODE;
        end

        BLIND_MODE: begin
            mu = 16'h0200;

            if (lock_detect)
                next_state = TRACKING;
            else if (lock_counter > 500)
                next_state = RETRAIN;
        end

        RETRAIN: begin
            // Reset coefficients
            for (int i = 0; i < 16; i++)
                eq_coeffs[i] = 16'b0;
            eq_coeffs[8] = 16'h1000;
            lock_counter = 8'b0;
            next_state = ACQUIRE;
        end

        LOCKED_ST: begin
            locked = 1'b1;
            mu = 16'h0080;  // Minimum step size

            if (!lock_detect) begin
                lock_counter <= lock_counter + 1;
                if (lock_counter > 20)
                    next_state = TRACKING;
            end else begin
                lock_counter <= 8'b0;
            end
        end

        UNLOCKED: begin
            // Signal loss detected
            next_state = ACQUIRE;
        end
    endcase
end

endmodule

module mesi_cache_controller (
    input logic clk,
    input logic rst_n,
    input logic [31:0] address,
    input logic cpu_read,
    input logic cpu_write,
    input logic bus_read,
    input logic bus_write,
    input logic [1:0] snoop_result,  // 00: HIT, 01: HIT_MODIFIED, 10: SHARED
    output logic [1:0] cache_state,   // 00: M, 01: E, 10: S, 11: I
    output logic bus_request,
    output logic cache_hit,
    output logic flush_cache
);

typedef enum logic [1:0] {
    MODIFIED   = 2'b00,
    EXCLUSIVE  = 2'b01,
    SHARED     = 2'b10,
    INVALID    = 2'b11
} mesi_state_t;

mesi_state_t state, next_state;
logic [31:0] tag_memory;
logic [31:0] current_address;
logic pending_bus_op;
logic [1:0] retry_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= INVALID;
        current_address <= 32'b0;
        pending_bus_op <= 1'b0;
        retry_count <= 2'b0;
    end else begin
        state <= next_state;

        // Update address on new access
        if (cpu_read || cpu_write) begin
            current_address <= address;
            pending_bus_op <= 1'b1;
        end

        // Clear pending operation after completion
        if (bus_read || bus_write)
            pending_bus_op <= 1'b0;

        // Retry logic
        if (state == next_state && state != INVALID && pending_bus_op)
            retry_count <= retry_count + 1;
        else
            retry_count <= 2'b0;
    end
end

always_comb begin
    next_state = state;
    cache_state = state;
    bus_request = 1'b0;
    cache_hit = 1'b0;
    flush_cache = 1'b0;

    // Tag comparison (simplified)
    logic tag_match;
    tag_match = (current_address == tag_memory);

    case (state)
        MODIFIED: begin
            cache_hit = 1'b1;

            // Local CPU access
            if (cpu_read || cpu_write) begin
                // Hit in modified state, no bus transaction needed
                next_state = MODIFIED;
            end

            // Snooped bus transactions
            if (bus_read) begin
                // Need to provide data and transition to shared
                next_state = SHARED;
                bus_request = 1'b1;  // Request bus to provide data
                flush_cache = 1'b1;  // Flush modified data
            end

            if (bus_write) begin
                // Another processor wants to write, invalidate
                next_state = INVALID;
                flush_cache = 1'b1;  // Flush before invalidating
            end

            // Snoop result processing
            unique case (snoop_result)
                2'b01: begin  // HIT_MODIFIED on another cache
                    next_state = SHARED;
                    flush_cache = 1'b1;
                end
                2'b10: begin  // SHARED on another cache
                    next_state = SHARED;
                end
            endcase
        end

        EXCLUSIVE: begin
            cache_hit = 1'b1;

            if (cpu_read) begin
                next_state = EXCLUSIVE;
            end else if (cpu_write) begin
                // Write to exclusive line -> becomes modified
                next_state = MODIFIED;
            end

            if (bus_read) begin
                // Another processor reading -> becomes shared
                next_state = SHARED;
            end

            if (bus_write) begin
                // Another processor writing -> invalidate
                next_state = INVALID;
            end
        end

        SHARED: begin
            cache_hit = 1'b1;

            if (cpu_read) begin
                next_state = SHARED;
            end else if (cpu_write) begin
                // Write to shared line -> need bus transaction
                next_state = MODIFIED;
                bus_request = 1'b1;  // Request bus for write
            end

            if (bus_write) begin
                // Another processor writing -> invalidate
                next_state = INVALID;
            end
        end

        INVALID: begin
            cache_hit = 1'b0;

            if (cpu_read || cpu_write) begin
                // Miss, need to fetch from memory
                bus_request = 1'b1;

                // Determine next state based on bus response
                if (snoop_result == 2'b10)  // Shared on other cache
                    next_state = SHARED;
                else if (cpu_read)
                    next_state = EXCLUSIVE;
                else if (cpu_write)
                    next_state = MODIFIED;
            end

            // Retry on bus contention
            if (retry_count == 2'b11) begin
                // Force exclusive access after retries
                next_state = EXCLUSIVE;
            end
        end
    endcase

    // Bus arbitration logic
    if (bus_request && (bus_read || bus_write))
        bus_request = 1'b0;  // Clear request when bus is busy
end

endmodule

module edge_detector_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic rising_edge
);

typedef enum logic {IDLE, HIGH} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else
        state <= next_state;
end

// Next state and output logic (Mealy)
always_comb begin
    next_state = state;
    rising_edge = 1'b0;

    case (state)
        IDLE: if (din) begin
            next_state = HIGH;
            rising_edge = 1'b1;  // Output depends on input
        end

        HIGH: if (!din)
            next_state = IDLE;
    endcase
end

endmodule
